# Debate with Pip and Pip's choice: Pip's feedback report at the end (what went well, what to work on, turn by turn).
R('/* ================= events ================= */', open(W+'debrep_block.js').read()+'\n/* ================= events ================= */')
R('@media (prefers-reduced-motion:reduce)','''.dbreport{gap:14px;text-align:left;max-width:760px;margin:0 auto 14px}
.dbr-top{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.dbr-top>div{flex:1;min-width:180px}.dbr-top h2{margin:2px 0}.dbr-top p{margin:0}.dbr-top .bigstars{margin:0;font-size:26px}
.dbr-k{font:700 12px/1 var(--body,inherit);letter-spacing:.08em;text-transform:uppercase;color:#22703A}
.dbr-overall{font-size:18px;line-height:1.5;margin:0;background:#F5FAEE;border-left:5px solid #2F8F46;border-radius:12px;padding:10px 14px}
.dbr-score{display:flex;flex-wrap:wrap;gap:8px}.dbr-score span{background:#FFF4D6;border-radius:999px;padding:6px 12px}
.dbr-sec h3{margin:0 0 6px;font-size:19px}.dbr-sec ul{margin:0;padding-left:20px;display:grid;gap:4px}
.dbr-good{background:#DDEFC4;border-radius:16px;padding:12px 14px}
.dbr-work{background:#FFE3D9;border-radius:16px;padding:12px 14px;display:grid;gap:8px}.dbr-work h3{margin:0}
.dbr-tip{display:grid;gap:2px;background:#fff;border-radius:12px;padding:8px 12px}.dbr-try{color:#22703A;font-weight:700}
.dbr-turns{list-style:none;padding:0;margin:0;display:grid;gap:10px}.dbr-turns li{border:2px solid var(--line,#e3ecd6);border-radius:16px;padding:10px 12px;display:grid;gap:4px}
.dbr-turns p{margin:0}.dbr-said{font-style:italic}.dbr-e{font-style:normal;font-size:24px}.dbr-fix{color:#5C4F45}.dbr-better{background:#F5FAEE;border-radius:10px;padding:6px 10px}
.dbr-goal{background:#FFF4D6;border-radius:16px;padding:10px 14px;margin:0;font-size:17px}
.dbr-wait{display:flex;gap:8px;align-items:center;margin:0;color:#5C4F45}.dbr-wait i{animation:dbdot 1s infinite;font-style:normal}.dbr-wait i:nth-child(3){animation-delay:.2s}.dbr-wait i:nth-child(4){animation-delay:.4s}
.dbr-acts{justify-content:center;flex-wrap:wrap}.dbr-acts .btn{min-height:44px}
.dbr-past{max-width:760px;margin:14px auto 0}.dbr-past ul{list-style:none;padding:0;margin:0;display:grid;gap:6px}.dbr-past .btn{width:100%;justify-content:flex-start;text-align:left;min-height:44px}
.dbr-wrap .dbr-cheer{text-align:center;margin-bottom:10px}.dbr-wrap .dbr-cheer h1{margin:4px 0}
@media print{.printdoc .noprint,.printdoc .dbr-acts{display:none!important}.printdoc .dbr-turns li{break-inside:avoid}}
@media (prefers-reduced-motion:reduce)''')
